@-moz-document domain("discord.com") {
/* Background Image - Replace URL with your own */
    body {
        background: url('https://i.pinimg.com/736x/00/dc/70/00dc70d2ab8247bdf6020a47adfa8abc.jpg') no-repeat center center fixed;
        background-size: cover;
    }

    /* Make main UI semi-transparent for a cute aesthetic */
    .appMount-2yBXZl,
    .app-2rEoOp,
    .bg-1QIAus,
    .container-2cd8Mz {
        background: rgba(255, 200, 220, 0.8) !important; /* Soft pink transparency */
        border-radius: 15px;
    }

    /* Customizing text & links */
    .title-31SJ6t,
    .channelName-3KPsGw,
    .username-1A8OIy {
        color: #ff90c2 !important; /* Cute pink text */
    }

    /* Custom Scrollbar */
    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-thumb {
        background: #ffb6c1; /* Light pink scrollbar */
        border-radius: 10px;
    }

    /* Button & Accent Colors */
    .button-38aScr,
    .lookFilled-1H2Jvj.colorBrand-3pXr91 {
        background: #ff90c2 !important;
        border-radius: 10px;
    }
    .button-38aScr:hover {
        background: #ff70a1 !important;
    }

    /* Input & Chat Box */
    .slateTextArea-1Mkdgw {
        background: rgba(255, 200, 220, 0.5) !important;
        border-radius: 10px;
        color: #ff69b4 !important;
    }
}
